S = "Hakeem Force Academy"
QS = [
 (S, "In which province of Pakistan is the Khewra salt mine located?", ["Sindh", "Punjab", "Balochistan", "Khyber Pakhtunkhwa"], 1,
  "The Khewra salt mine lies in the Salt Range near Khewra in Jhelum district, in northern Punjab.",
  "Khewra is one of the largest and oldest salt mines in the world.", [2473, 4156]),
 (S, "The Khilafat Movement in India arose mainly because of which event?", ["The Nehru Report", "The defeat of the Ottoman Empire in the First World War and the threat to the Caliphate", "The Partition of Bengal", "The Simon Commission"], 1,
  "After the First World War the Allies defeated Turkey and threatened the Ottoman Caliph, so Indian Muslims launched the movement to save the Caliphate.",
  "The Nehru Report (1928) came years after the Khilafat Movement (1919-1924).", [2729]),
 (S, "Amir Khusro is regarded as the first poet of which language (in its early form)?", ["Pashto", "Urdu", "Sindhi", "Punjabi"], 1,
  "Amir Khusro (1253-1325) composed verse in Hindavi, the early form of Urdu, and is called its first poet.",
  "Amir Khusro also wrote in Persian and was a disciple of Hazrat Nizamuddin Auliya.", [1486, 1489]),
 (S, "Who led the Muslim army in the Battle of Khyber?", ["Hazrat Umar (RA)", "Hazrat Khalid bin Walid (RA)", "The Holy Prophet Muhammad (PBUH)", "Hazrat Abu Bakr (RA)"], 2,
  "The Battle of Khyber (7 AH) was fought against the Jews of Khyber and the Muslim army was led by the Holy Prophet (PBUH) himself.",
  "The main fort Qamus was conquered at the hands of Hazrat Ali (RA).", [5162]),
 (S, "Which animal did the people of Thamud kill, despite the warning of Prophet Salih (AS)?", ["A sheep", "A she-camel", "A horse", "A cow"], 1,
  "The nation of Thamud killed the she-camel sent by Allah as a miracle for Prophet Salih (AS), and was then destroyed.",
  "The people of Thamud lived at Al-Hijr in northern Arabia.", [1113, 4253]),
 (S, "In mathematics, subtraction is which kind of operator?", ["Unary operator", "Binary operator", "Ternary operator", "Logical operator"], 1,
  "Subtraction needs two operands (a - b), so it is a binary arithmetic operator.",
  "The minus sign used with one number, as in -5, acts as a unary operator.", [2697]),
 (S, "Sikandar (Alexander the Great) was the king of which land?", ["Macedonia", "Persia", "Egypt", "Rome"], 0,
  "Alexander the Great was king of Macedonia, a kingdom in northern Greece, and invaded India in 326 BC.",
  "He fought King Porus at the Battle of the Hydaspes (Jhelum) in present-day Pakistan.", [2681]),
 (S, "Which prophet was blessed with a great kingdom, including control over jinn, birds and wind?", ["Hazrat Ibrahim (AS)", "Hazrat Musa (AS)", "Hazrat Isa (AS)", "Hazrat Sulaiman (AS)"], 3,
  "Allah gave Hazrat Sulaiman (AS) a vast kingdom and command over jinn, birds and wind.",
  "His father Hazrat Dawud (AS) was also given kingship along with prophethood.", [778, 1171, 4645]),
 (S, "The Kirthar range lies mainly along the border of which two provinces of Pakistan?", ["Punjab and Sindh", "Sindh and Balochistan", "Punjab and Balochistan", "Khyber Pakhtunkhwa and Punjab"], 1,
  "The Kirthar range runs north to south along the Sindh and Balochistan border.",
  "Kirthar National Park in Sindh is named after this range.", [2479]),
 (S, "What is the approximate maximum height of the Kirthar range (its highest point, Zardak Peak)?", ["About 2,260 metres (7,400 feet)", "About 4,500 metres", "About 1,000 metres", "About 6,000 metres"], 0,
  "The highest point of the Kirthar range is Zardak Peak at roughly 2,260 metres, or about 7,400 feet.",
  "Sources give slightly different figures, from about 2,260 to 2,267 metres.", [101]),
 (S, "What is the meaning of the word 'kith' (as in 'kith and kin')?", ["Enemies", "Friends and acquaintances", "Strangers", "Servants"], 1,
  "Kith means one's friends, neighbours and acquaintances, while kin means blood relatives.",
  "Candidates often answered relatives, but that is the meaning of kin.", [3513, 870]),
 (S, "What is the antonym of 'kith'?", ["Friend", "Neighbour", "Stranger", "Acquaintance"], 2,
  "Kith means friends and acquaintances, so its opposite is a stranger.",
  "The phrase 'kith and kin' means friends and relatives.", [460]),
 (S, "What was the old name of Khyber Pakhtunkhwa (KPK)?", ["Frontier Gandhara", "North-West Frontier Province (NWFP)", "Pakhtunistan", "Tribal Province"], 1,
  "The province was known as the North-West Frontier Province (NWFP) until it was renamed in 2010.",
  "FATA was later merged into Khyber Pakhtunkhwa in 2018.", [1001]),
 (S, "Hazrat Umm Kulsoom (RA) was what to the Holy Prophet (PBUH)?", ["Wife", "Daughter", "Aunt", "Mother"], 1,
  "Hazrat Umm Kulsoom (RA) was a daughter of the Holy Prophet (PBUH) and Hazrat Khadija (RA).",
  "She was married to Hazrat Usman (RA) after the death of her sister Hazrat Ruqayyah (RA).", [1746, 3693, 3976]),
 (S, "On which date is Labour Day (International Workers' Day) observed?", ["1 January", "1 May", "1 June", "23 March"], 1,
  "Labour Day is observed every year on 1 May, including in Pakistan, where it is a public holiday.",
  "The day commemorates the Haymarket affair of Chicago in 1886.", [476, 4361]),
 (S, "Which woman is mentioned by name in the Holy Quran?", ["Hazrat Khadija (RA)", "Hazrat Ayesha (RA)", "Hazrat Fatima (RA)", "Hazrat Maryam (AS)"], 3,
  "Hazrat Maryam (AS), the mother of Hazrat Isa (AS), is the only woman named in the Quran.",
  "Surah Maryam (Chapter 19) of the Quran is named after her.", [4490]),
 (S, "In which valley is Ansoo Lake located?", ["Swat Valley", "Kaghan Valley", "Hunza Valley", "Neelum Valley"], 1,
  "Ansoo (Lake Ansoo) is a tear-shaped high-altitude lake in the Kaghan Valley of Khyber Pakhtunkhwa.",
  "Lake Saif-ul-Malook is also in the Kaghan Valley.", [1090]),
 (S, "The word 'Pakistan' means the land of what?", ["The brave", "The pure", "The rivers", "The mountains"], 1,
  "Pakistan means 'Land of the Pure' (Pak means pure and stan means land).",
  "The name was coined by Choudhry Rahmat Ali in 1933.", [800, 2606]),
]
